// Contenu du guide IRS
window.GUIDE = {"codePenal": {"key": "CP", "label": "Code pénal (extraits)", "source": "Code pénal de San Andreas", "groups": [{"title": "Argent - Art. 7", "items": [{"article": "7.1", "resume": "Plus de 2 000 $ en liquide sans justificatif : saisie + amende de 50 % de la somme non déclarée.", "usage": "Contrôle des caisses ; règle « Paiement en liquide »."}, {"article": "7.2", "resume": "Blanchiment avéré : amende de 5 $ x la somme blanchie + prison fédérale.", "usage": "Entreprises façades, structuration."}, {"article": "7.3", "resume": "Impôts d'entreprise non payés : saisie de l'entreprise + amende.", "usage": "Base de la saisie pour impôts impayés."}, {"article": "7.4", "resume": "Détournement de fonds : amende de 2 $ x la somme détournée + prison fédérale.", "usage": "Usage personnel de la trésorerie, emplois fictifs."}, {"article": "7.5", "resume": "Fraude fiscale : amende de 2,5 $ x la somme non payée + prison fédérale.", "usage": "Fausse déclaration volontaire, revenus cachés."}, {"article": "7.6", "resume": "Amendes non payées : saisie à la source, puis saisie par l'IRS des biens de valeur (véhicules, propriétés, liquidités, bijoux, vêtements de luxe) + amende + TIG + bracelet ; si paiement impossible, conversion en UP.", "usage": "Recouvrement."}, {"article": "7.7", "resume": "Corruption : amende + prison fédérale.", "usage": "Tentative d'acheter un agent IRS ; agent qui accepte."}, {"article": "7.8", "resume": "L'IRS a un droit de regard de 3 mois en arrière, à partir du début de l'enquête, pour la fraude fiscale et le détournement.", "usage": "Période contrôlable."}]}, {"title": "Procédure et mandats", "items": [{"article": "1.2", "resume": "Pas de fouille sans raison particulière, sauf flagrant délit.", "usage": "L'IRS ne fouille pas les personnes."}, {"article": "2.1", "resume": "Mandat de perquisition délivré par le juge et le bureau du procureur, valable 14 jours.", "usage": "Accès forcé aux locaux ou au domicile."}, {"article": "2.2 / 2.3", "resume": "Perquisition en présence du propriétaire (15 min pour venir), sinon du bureau du procureur.", "usage": "Déroulé d'une perquisition fiscale."}, {"article": "2.6", "resume": "Mandat d'arrêt pour non-présentation à convocation (30 min pour venir), délivré par le juge, valable 14 jours.", "usage": "Gérant qui ne répond pas à une convocation."}, {"article": "2.8", "resume": "Sans flagrant délit ni appel d'urgence, entrer dans une propriété privée sans accord exige un mandat.", "usage": "Contrôle sur place refusé."}, {"article": "2.9", "resume": "Flagrant délit : régime valable 24h.", "usage": ""}, {"article": "2.10", "resume": "Loi RICO : poursuite de toutes les personnes impliquées dans des activités criminelles organisées.", "usage": "Réseaux de blanchiment."}, {"article": "3.1", "resume": "Fouille du téléphone seulement pour un crime, avec preuve et accord d'un juge fédéral.", "usage": "Hors pouvoirs de l'IRS."}]}, {"title": "Infractions liées", "items": [{"article": "4.6", "resume": "Le conducteur est responsable du contenu du véhicule.", "usage": "Véhicules d'entreprise."}, {"article": "8.23", "resume": "Vol de véhicule (délit mineur) : 200 $.", "usage": "Véhicule d'occasion d'origine douteuse."}, {"article": "15.4", "resume": "Usage de fausses plaques d'immatriculation (délit majeur) : 1 000 $ + 40 min.", "usage": "Revente de véhicules volés ou maquillés."}, {"article": "8.27", "resume": "Recel : détenir, acheter, vendre un bien volé.", "usage": "Pawnshops, ventes de véhicules."}, {"article": "12.3 / 15.8", "resume": "Entrave à la justice ; obstruction (refus de coopérer, dissimulation, intimidation).", "usage": "Refus de contrôle délibéré."}, {"article": "12.4", "resume": "Non-respect d'une ordonnance ou injonction d'un magistrat.", "usage": "Fermeture ou interdiction de gérer non respectée."}, {"article": "12.8", "resume": "Diffamation.", "usage": "Dénonciation mensongère."}, {"article": "12.9", "resume": "Discrimination.", "usage": "Licenciements, embauches."}, {"article": "12.10", "resume": "Abus de pouvoir.", "usage": "Devoirs des agents IRS."}, {"article": "13.1", "resume": "Association de malfaiteurs (plus de 3 personnes).", "usage": "Entreprise servant de façade."}, {"article": "14.5", "resume": "Dissimulation de preuves (détruire ou altérer un document).", "usage": "Comptabilité détruite."}, {"article": "15.1", "resume": "Parjure.", "usage": "Fausse déclaration sous serment."}, {"article": "15.2", "resume": "Faux et usage de faux.", "usage": "Fausses factures, contrats falsifiés."}, {"article": "15.3", "resume": "Usurpation d'identité.", "usage": "Prête-noms."}, {"article": "15.6", "resume": "Influence de témoin.", "usage": "Pression sur un employé témoin."}, {"article": "16.6", "resume": "Divulgation d'informations confidentielles.", "usage": "Secret fiscal."}, {"article": "21.1 / 21.2", "resume": "Récidive : au 3e délit majeur, procès ; au 3e délit mineur, amende + prison fédérale.", "usage": "Barème type 2."}, {"article": "22.7", "resume": "Arnaque ou fraude informatique.", "usage": "Annonces trompeuses."}]}, {"title": "Règles de procédure", "items": [{"article": "Constitution de l'infraction", "resume": "Intention ou négligence grave, et infraction prévue par la loi.", "usage": "Erreur de bonne foi : redressement, pas de poursuite."}, {"article": "Responsabilité 3", "resume": "Effacement du casier sur décision d'un juge (mineur > 1 mois, majeur > 3 mois).", "usage": "Inéligibilité des cadres."}, {"article": "Culpabilités", "resume": "Tentative ; complicité punie de la moitié de la peine ; co-auteurs.", "usage": "Trésorier complice."}, {"article": "Travail d'intérêt général", "resume": "Non payé ; 5 jours maximum, 30 minutes par jour.", "usage": "Recouvrement (art. 7.6)."}, {"article": "Comparution immédiate / Procès", "resume": "Comparution immédiate : délits majeurs. Procès : crime ou récidive de délit majeur.", "usage": "Suite des dossiers transmis au DOJ."}, {"article": "Conflit d'intérêt", "resume": "Le déclarer à sa hiérarchie et s'abstenir.", "usage": "Agents IRS."}, {"article": "Délais de procédure", "resume": "Après lecture des droits : 30 min sans début de procédure = réduction de peine, 1h = abandon des charges. Avocat : 15 min.", "usage": "Arrestations faites par les FDO à la suite d'un dossier IRS."}, {"article": "19.1 à 19.4", "resume": "Vice de procédure apprécié par le juge ; preuve issue d'une fouille ou arrestation illégale = nulle.", "usage": "Documents obtenus hors pouvoirs."}, {"article": "20.1 à 20.3", "resume": "Vide juridique : interprétation par le juge ; à défaut, relaxe et conseil pour proposer une loi.", "usage": "Une sanction doit reposer sur un texte écrit en vigueur."}]}]}, "droits": {"key": "DC", "label": "Droits du contribuable", "updated": "31/10/2026", "articles": [{"id": "DC.1", "title": "Être informé", "body": "Connaître les règles fiscales applicables et recevoir une explication claire de toute décision de l'IRS (motif de l'amende, calcul).", "proposition": false}, {"id": "DC.2", "title": "Un service de qualité", "body": "Être reçu avec courtoisie et recevoir une réponse dans un délai raisonnable ; pouvoir demander à parler au Chef IRS.", "proposition": false}, {"id": "DC.3", "title": "Ne payer que le montant dû", "body": "Ne payer que l'impôt réellement dû, intérêts et pénalités compris, et voir les paiements correctement enregistrés.", "proposition": false}, {"id": "DC.4", "title": "Contester et être entendu", "body": "Présenter des documents et des explications avant qu'une sanction soit définitive.", "proposition": false}, {"id": "DC.5", "title": "Faire appel devant une instance indépendante", "body": "Contester une décision auprès du Chef IRS, puis devant un juge du DOJ.", "proposition": false}, {"id": "DC.6", "title": "Sécurité juridique", "body": "Connaître le délai maximal d'un contrôle et savoir quand un dossier est clos (voir « Prescription »).", "proposition": false}, {"id": "DC.7", "title": "Respect de la vie privée", "body": "Un contrôle ne va pas au-delà de ce qui est nécessaire. Les comptes personnels ne sont consultés qu'avec un mandat d'un procureur ou d'un juge. Pas de fouille corporelle ni de fouille de téléphone par l'IRS (art. 1.2 et 3.1).", "proposition": false}, {"id": "DC.8", "title": "Confidentialité", "body": "Les informations fiscales ne sont pas divulguées en dehors des cas prévus. Un agent qui divulgue ou consulte un dossier sans motif est sanctionné (divulgation d'informations confidentielles, art. 16.6 ; abus de pouvoir, art. 12.10).", "proposition": false}, {"id": "DC.9", "title": "Être représenté", "body": "Se faire assister ou représenter par un avocat ou un comptable lors d'un contrôle.", "proposition": false}, {"id": "DC.10", "title": "Pas de sanction sans texte", "body": "Une sanction doit reposer sur une règle écrite en vigueur. En cas de vide juridique, la personne est relaxée (art. 20.3). Il n'y a infraction pénale qu'en cas d'intention ou de négligence grave (Règles de procédure, « Constitution de l'infraction »).", "proposition": false}, {"id": "DC.11", "title": "Preuves régulières", "body": "Un document obtenu en dehors des pouvoirs de l'agent (sans mandat lorsqu'il en faut un) n'a pas de valeur probante (art. 19.3 et 19.4). Seul un juge apprécie un vice de procédure (art. 19.1).", "proposition": false}, {"id": "DC.12", "title": "Un système fiscal juste", "body": "Obtenir des délais ou un échelonnement en cas de difficulté réelle (voir « Difficultés de paiement »).", "proposition": false}], "etapes": [{"id": "DC.E1", "title": "1. Notification", "body": "L'agent remet un avis écrit : objet du contrôle, période contrôlée, documents demandés, délai de remise (24 à 48h).", "proposition": false}, {"id": "DC.E2", "title": "2. Entretien", "body": "Le gérant ou le trésorier présente l'activité. Il peut être assisté d'un avocat ou d'un comptable.", "proposition": false}, {"id": "DC.E3", "title": "3. Examen", "body": "L'agent vérifie documents, contrats, comptes et registres. Il peut demander des justificatifs complémentaires.", "proposition": false}, {"id": "DC.E4", "title": "4. Rapport", "body": "L'agent rédige un rapport listant chaque irrégularité, la règle enfreinte et la sanction proposée.", "proposition": false}, {"id": "DC.E5", "title": "5. Validation", "body": "Le Chef IRS valide les amendes proposées.", "proposition": false}, {"id": "DC.E6", "title": "6. Notification de l'avis", "body": "Avis positif ou négatif remis par écrit à l'entreprise, avec les montants et délais.", "proposition": false}, {"id": "DC.E7", "title": "7. Contestation", "body": "48h pour contester par écrit auprès du Chef IRS, puis recours devant un juge du DOJ. La contestation suspend la majoration, pas le paiement des impôts non contestés.", "proposition": false}, {"id": "DC.E8", "title": "8. Recouvrement", "body": "Si rien n'est payé ni contesté dans les délais : majoration, avis final, saisie (voir onglet Fiscalité).", "proposition": false}], "references": "Code pénal : art. 1.2, 2.1, 2.8, 3.1, 12.10, 16.6, 19.1 à 19.4, 20.3 ; Règles de procédure (Constitution de l'infraction, Conflit d'intérêt)."}, "entreprises": {"key": "CE", "label": "Code Entreprises", "updated": "22/11/2026", "articles": [{"id": "CE.1", "title": "Déclaration des comptes & paiement des impôts", "body": "À chaque changement de gérant (PDG) ou de trésorier, la personne entrante remet un état des comptes au Gouvernement et à l'IRS dans les 24h suivant sa prise de fonction.\n\nLe gérant ou manager de chaque entreprise, ainsi que chaque auto-entrepreneur, doit déclarer et payer ses impôts selon la procédure de l'onglet « Impôts ».\n\nChaque entreprise tient une comptabilité permettant de justifier chaque montant déclaré (factures, relevés, contrats, registre du personnel).", "penal": "Art. 7.3 : impôts d'entreprise non payés = saisie de l'entreprise + amende.", "proposition": false}, {"id": "CE.2", "title": "Emploi fictif", "body": "Une personne est suspectée d'emploi fictif lorsqu'elle perçoit une rémunération pour une activité qu'elle n'exerce pas.\nExemple : exercer une activité partisane ou militante au lieu d'effectuer le travail pour lequel elle est rémunérée.\n\nSont aussi visés les « employés fantômes » : personnes inscrites au registre et payées sans travailler, ou n'existant pas. Le bénéficiaire ET la personne qui organise le versement sont poursuivis pour détournement de fonds. Les sommes versées doivent être remboursées.", "penal": "Art. 7.4 : détournement de fonds, amende de 2 $ x somme détournée + prison fédérale.\nRègles de procédure, « Culpabilités » : le complice est puni de la moitié de la peine.", "proposition": false}, {"id": "CE.3", "title": "Âge minimum légal pour travailler", "body": "Poste de direction : 21 ans\nCDD / CDI : 16 ans\nStagiaire : 14 ans\n\nEmplois nécessitant 21 ans minimum :\n- Service public (SAMD, SASP, DOJ)\n- Mairie\n- Gouvernement\n- Barman (préparation et service d'alcool au bar)\n\nPostes dangereux (chantier, mine, abattage, remorquage, transport de fonds, manipulation d'armes ou d'explosifs) : 21 ans minimum. Les 14-15 ans ne peuvent occuper que des postes sans danger.", "proposition": false}, {"id": "CE.4", "title": "Stage", "body": "Les entreprises peuvent proposer des stages encadrés. Un tuteur doit être désigné et la période ne peut excéder 1 mois. La rémunération est facultative (0 % ou jusqu'à 80 % maximum).\n\nLe stage doit profiter principalement au stagiaire (formation). Un stagiaire non rémunéré ne peut pas remplacer un employé ni travailler seul pour générer du chiffre d'affaires. À défaut, le stage est requalifié en emploi et le stagiaire doit être payé au barème salarial.", "proposition": false}, {"id": "CE.5", "title": "Fonction publique", "body": "La fonction publique (Police, Gouvernement, LSFD, BCFD, SAMD, Mairie, DOJ, SASP) ne recrute que du personnel au casier judiciaire vierge de tout délit majeur ou crime. Toute condamnation de ce type entraîne un renvoi immédiat. Une fois le casier effacé par décision d'un juge, la personne peut à nouveau se porter candidate.\n\nSecteur privé : l'employeur peut consulter le casier d'un candidat, mais un refus d'embauche doit être lié au poste (ex. : trésorier condamné pour fraude, chauffeur condamné pour conduite dangereuse).", "penal": "Règles de procédure, « Responsabilité » : un juge peut effacer le casier (délit mineur de plus d'1 mois, délit majeur de plus de 3 mois).", "proposition": false}, {"id": "CE.6", "title": "Gérance des entreprises et auto-entrepreneurs", "body": "Entreprises gérées\nLes entreprises sont la propriété du gouvernement, avec un système de gérance. Le gérant est nommé par le gouvernement ou la mairie à la suite d'un appel à candidature. L'entreprise doit ensuite être déclarée auprès de l'IRS.\n\nEntreprises privées\nLes entreprises exemptées du système de gérance et de la propriété gouvernementale sont des entreprises privées (ex. : agence immobilière).\n\nAuto-entrepreneurs\nMétiers concernés : décorateur d'intérieur/extérieur, photographe, comptable ou autres.\nChaque auto-entrepreneur se déclare à la mairie et à l'IRS. Il ne peut avoir qu'un seul employé, lui-même compris. Il est soumis aux mêmes obligations et sanctions que les entreprises.\n\nPerte de fonction (gérant, manager, DRH, trésorier ou entrepreneur)\n- Décès\n- Condamnation pour crime ou délit majeur (avec approbation du DOJ ou de l'IRS)\n- Absence non justifiée de plus d'une semaine (sans intérim organisé ; intérim de 3 semaines maximum)\n- Choix personnel du PDG\n- Décision de la mairie ou du gouvernement (2 blâmes = révocation)\n\nInéligibilité à un poste de cadre\nToute personne condamnée pour fraude fiscale ou détournement de fonds ne peut exercer un poste de cadre (manager, DRH, gérant, trésorier) pendant au moins un mois et demi, durée pouvant être prolongée par la mairie ou l'IRS.", "penal": "Art. 7.4 (détournement) et 7.5 (fraude fiscale) : condamnations qui rendent inéligible.\nArt. 12.4 : ne pas respecter une interdiction prononcée par un magistrat = non-respect d'injonction.", "proposition": false}, {"id": "CE.7", "title": "Inactivité", "body": "Toute entreprise ou organisation non déclarée, ne payant pas ses impôts de façon répétée pendant au moins 2 semaines, ou sans activité concrète, peut être reprise de manière forcée par le gouvernement pour réattribution.\n\nAvant reprise forcée, un avis écrit est adressé au gérant, qui dispose de 48h pour régulariser.", "penal": "Art. 7.3 : saisie de l'entreprise pour impôts non payés.", "proposition": false}, {"id": "CE.8", "title": "Modification d'entreprise et organisation", "body": "Toute modification doit être déclarée au gouvernement et à l'IRS dans les 24h qui suivent :\n- Changement de lieu du siège social\n- Changement de nom\n- Changement d'activité\n- Changement de gérant\n\nÀ défaut, l'activité est considérée comme une activité commerciale non déclarée.", "proposition": false}, {"id": "CE.9", "title": "Période d'essai", "body": "L'une ou l'autre des parties peut rompre librement le contrat pendant la période d'essai, sans justification, selon les termes du contrat de travail. Les heures travaillées pendant l'essai restent dues au barème.", "proposition": false}, {"id": "CE.10", "title": "Règlement intérieur et droit disciplinaire", "body": "Chaque entreprise, organisation ou service public possède un règlement intérieur validé par un avocat (ou par la direction pour les services publics, sous forme de code de déontologie).\nChaque entreprise possède des contrats de travail validés par un avocat.\n\nLe règlement intérieur contient au minimum :\n- Les règles de sécurité et de prévention des risques\n- L'interdiction du harcèlement et des discriminations, et la procédure de plainte\n- L'échelle des sanctions disciplinaires (avertissement, blâme, mise à pied, licenciement)\n- Les règles sur les tenues, véhicules de fonction et EPI", "penal": "Art. 12.9 : discrimination.", "proposition": false}, {"id": "CE.11", "title": "Rupture du contrat de travail à durée indéterminée", "body": "Le CDI est automatiquement rompu dans l'un des cas suivants :\n- Absence de plus de deux semaines sans en avoir informé l'employeur\n- Absence de plus de deux semaines, même signalée à l'avance (l'employeur peut reprendre l'employé à son retour)\n\nLe CDI peut être rompu sur décision immédiate du gérant pour :\n- Condamnation pour délit majeur ou crime\n- Non-respect du règlement intérieur ou des clauses du contrat\n\nLicenciement interdit : pour un motif discriminatoire, ou en représailles d'un signalement fait à l'IRS, à la mairie ou à la justice.", "penal": "Art. 12.9 : discrimination.\nArt. 15.6 : licencier pour faire pression sur un témoin = influence de témoin.", "proposition": false}, {"id": "CE.12", "title": "Solde de tout compte", "body": "Le solde de tout compte regroupe les rémunérations et indemnités dues au salarié à la fin du contrat (prévues au contrat et/ou au règlement intérieur). Il est dû quel que soit le motif de la rupture.\n\nDélais de paiement :\n- Licenciement ou fin d'essai à l'initiative de l'employeur : paiement dans les 24h\n- Démission avec préavis : paiement le dernier jour travaillé\n- Démission sans préavis : paiement sous 72h\n\nL'employeur remet un « reçu pour solde de tout compte ». En cas de retard volontaire, pénalité de 1/7e du salaire hebdomadaire par jour de retard, plafonnée à 30 jours. Le salarié peut saisir l'IRS ou le DOJ pendant 30 jours.", "proposition": false}, {"id": "CE.13", "title": "Bénévolat", "body": "Le bénévolat est reconnu à Los Santos et à Blaine County uniquement au sein d'associations à but non lucratif et de services publics.\nUn bénévole ne touche ni salaire ni revenu. Un contrat de bénévolat rédigé par un avocat prouve son activité.\n\nUne entreprise commerciale ne peut pas employer de bénévoles : tout « bénévole » d'une entreprise est considéré comme un employé non déclaré.", "proposition": false}, {"id": "CE.14", "title": "Maison de disque, labels, artistes", "body": "Les labels sont recensés auprès du Gouvernement ou de la Mairie de leur comté, ainsi qu'auprès de la maison de disque officielle (Rockford Record).\nLes labels prennent une marge sur les revenus des artistes provenant de l'application musicale, et doivent avoir un contrat avec la maison de disque pour percevoir une rémunération liée aux écoutes.\nLes artistes et labels résident à Los Santos ou dans le Blaine County et doivent pouvoir prouver qu'ils sont les auteurs de leurs productions.\nLes artistes indépendants négocient directement leur contrat avec la maison de disque.\n\nToute cession de droits sur une œuvre doit être écrite et signée. Les redevances (royalties) sont des revenus à déclarer.", "proposition": false}, {"id": "CE.15", "title": "Obligations du gérant d'une entreprise", "body": "Gestion et obligations du gérant\nLe gérant fournit un état des comptes. Si la trésorerie est négative, le précédent gérant doit justifier les comptes et aucune prime ne peut être réclamée.\nLe gérant est passible de poursuites pour détournement de fonds si l'IRS n'a pas été informé du changement de gérant et n'a pas pu enquêter sur les comptes avant la reprise.\n\nObligations du nouveau gérant\n- Maintien des salariés en place (sécurité de l'emploi)\n- Les employés peuvent repasser une phase de test d'une semaine, sans perte de leurs avantages financiers (taux appliqué au départ du précédent gérant)\n\nResponsabilité personnelle\nLe gérant et le trésorier sont personnellement responsables des impôts dus et non payés par l'entreprise lorsqu'ils avaient le pouvoir de les payer.\n\nConditions de reprise\nUne autorisation de reprise de l'IRS ou de la mairie est requise avant toute mise en vente.", "penal": "Art. 7.4 : détournement de fonds.\nArt. 7.8 : l'IRS peut remonter 3 mois avant l'ouverture de l'enquête.", "proposition": false}, {"id": "CE.16", "title": "Achat / vente de véhicule appartenant à l'entreprise", "body": "Acquisition\nToute acquisition d'un véhicule par une entreprise (achat, apport du gérant, don, location) suit les lois existantes et doit être homologuée par l'IRS.\nPour chaque véhicule, une demande est adressée à l'IRS avec un devis d'un concessionnaire. L'acquisition n'a lieu qu'après accord écrit de l'IRS, qui répond dans un délai d'une semaine.\nUn véhicule acquis sans accord de l'IRS expose le dirigeant à une amende de 70 % du prix d'achat et à la saisie du véhicule (barème B.12).\n\nVente\n- Prix minimum : 60 % du prix concessionnaire du même modèle, comme entre particuliers.\n- Le prix de vente est versé sur le compte bancaire de l'entreprise.\n- Le contrat de vente est enregistré au registre des ventes d'occasion tenu par l'IRS.\n\nContrôle\nL'IRS, la mairie ou le gouvernement peuvent demander à tout moment la liste des véhicules de l'entreprise et leurs justificatifs d'achat. Sans justificatif sous 48h, le véhicule peut être saisi.\nLes autorités peuvent juger un véhicule non conforme à l'activité ; le dirigeant peut alors le revendre, aux conditions ci-dessus, sur présentation d'une preuve de vente.\n\nCarnet d'usage\nChaque véhicule d'entreprise a un carnet d'usage (conducteur, date, motif du trajet), présentable lors d'un contrôle.\n\nVéhicules saisis\nLes véhicules saisis par l'IRS sont revendus aux enchères. Mise à prix : 30 % du prix concessionnaire. Le produit de la vente vient en déduction de la dette de l'entreprise.", "penal": "Art. 4.6 : le conducteur est responsable du contenu du véhicule.\nArt. 7.4 : détournement de fonds (prix de vente détourné).\nArt. 7.6 : saisie des véhicules pour amendes impayées.", "proposition": false, "effect": "- Acquisition sans accord de l'IRS : 70 % du prix d'achat + saisie (B.12).\n- Vente sous 60 % : somme manquante pour atteindre 60 % du prix concessionnaire, à la charge de l'entreprise (B.19).\n- Prix de vente non versé sur le compte de l'entreprise : détournement de fonds (art. 7.4).\n- Vol d'un véhicule d'entreprise : amende de 1 000 $."}, {"id": "CE.17", "title": "Achat / vente de propriété appartenant à l'entreprise", "body": "L'IRS, la mairie ou le gouvernement peuvent demander à tout moment la liste des propriétés de l'entreprise et leurs justificatifs d'achat.\nSans justificatif sous 48h, la propriété peut être saisie.\nLes autorités peuvent juger une propriété non conforme à l'activité ; le dirigeant peut alors la revendre sur présentation d'une preuve de vente.\n\nUne propriété d'entreprise ne peut pas servir de logement personnel au dirigeant, sauf accord écrit de l'IRS (sinon avantage en nature à déclarer).", "penal": "Art. 7.6 : saisie des propriétés pour amendes impayées.", "proposition": false}, {"id": "CE.18", "title": "Publicité et marketing", "body": "La publicité doit être honnête et ne pas induire les consommateurs en erreur :\n- Les prix affichés sont les prix facturés\n- Une promotion indique sa durée\n- Les qualités annoncées d'un produit ou service doivent être vraies et vérifiables\n- Une offre d'emploi annonce le vrai poste et le vrai salaire", "penal": "Art. 22.7 : arnaque en ligne (annonce sans remise du bien).", "proposition": false}, {"id": "CE.19", "title": "Pratiques commerciales déloyales", "body": "Les pratiques commerciales déloyales sont interdites et passibles de sanctions pénales, notamment :\n- Publicité mensongère\n- Vente de produits contrefaits ou d'imitations d'une marque\n- Dénigrement mensonger d'un concurrent\n- Toute action visant à tromper le consommateur", "penal": "Art. 22.7 : arnaque / fraude informatique.\nArt. 15.2 : faux et usage de faux.", "proposition": false}, {"id": "CE.20", "title": "Annonces d'entreprise", "body": "Toute annonce de vente au nom d'une entreprise non déclarée, publiée sur un réseau de la ville (Annonces, Pages Jaunes, Marketplace, Birdy, Instapic), doit obtenir l'accord préalable de la mairie et les revenus doivent être déclarés à l'IRS.\n\nLa mairie, le gouvernement ou l'IRS peuvent contrôler les annonces d'ouverture d'entreprise pour vérifier qu'elles ne sont ni trompeuses ni illégales.\nEn cas d'infraction, des saisies financières peuvent être engagées (une saisie par jour au maximum).", "penal": "Art. 22.7 ; art. 22.10 : ces peines visent les publications sur les réseaux sociaux.", "proposition": false}, {"id": "CE.21", "title": "Régulation de la vente et de l'achat de produits / véhicules / propriétés", "body": "Vente de véhicules entre particuliers : voir Code Citoyen, « Vente et achat de véhicules entre particuliers ».\n\nActivité commerciale de vente ou rachat\nSeules les concessions automobiles sont dispensées de la limite de transactions. Le prix minimum de 60 % s'applique aussi aux rachats de véhicules par une concession.\nLes personnes exerçant une activité de vente ou rachat de véhicules se déclarent à la mairie (validation requise) et à l'IRS, et respectent les obligations comptables et fiscales des entreprises.\n\nAutres biens : les pawnshops (produits) et les agences immobilières (propriétés) sont dispensés de la limite de transactions.\n\nUne personne qui dépasse la limite de transactions entre particuliers exerce une activité commerciale et doit se déclarer.", "penal": "Art. 8.23 : vol de véhicule.\nArt. 8.27 : recel (vendre ou acheter un bien volé).\nArt. 15.4 : usage de fausses plaques.", "proposition": false, "effect": "- Activité de vente ou rachat non déclarée, ou dépassement de la limite : exercice illégal d'une activité professionnelle (barème B.11).\n- Rachat par une concession sous 60 % du prix concessionnaire : barème B.19."}, {"id": "CE.22", "title": "Contrat de partenariat", "body": "Un contrat de partenariat écrit entre deux entreprises est obligatoire. Il est établi par un avocat à la demande de l'une des entreprises, signé par les deux parties, et indique précisément les termes convenus (contreparties, montants, durée, conditions de rupture). Tous les termes doivent être conformes aux lois en vigueur.\n\nLes sommes échangées dans le cadre d'un partenariat sont déclarées par chaque entreprise.", "proposition": false}, {"id": "CE.23", "title": "Contrôles sanitaires et de sécurité - objets illicites ou interdits", "body": "Si, lors d'un contrôle sanitaire et de sécurité, l'IRS ou la mairie constate la présence d'objets illicites ou interdits dans les locaux d'une entreprise :\n\n- L'IRS ou la mairie peut saisir les objets interdits mais non illicites (parachute, radio, armes non autorisées, drogues légères, etc. ; liste non exhaustive)\n- Pour les objets illicites, l'IRS ou la mairie ne saisit pas directement : elle alerte les autorités compétentes (FIB, SASP, etc.), qui interviennent selon leurs procédures.\n\nUn contrôle administratif ne sert pas à fouiller les lieux à la recherche d'un crime : il se limite aux locaux professionnels et aux documents liés au contrôle.\nSi le gérant refuse l'accès aux locaux, l'agent ne force pas l'entrée : il constate le refus (voir « Refus de contrôle », onglet Fiscalité) et demande un mandat (art. 2.1 et 2.8). L'agent ne fouille ni les personnes ni les téléphones (art. 1.2 et 3.1).", "penal": "Art. 2.1 et 2.8 : sans accord ni flagrant délit, entrer dans une propriété privée exige un mandat (juge + procureur, 14 jours).\nArt. 1.2 et 3.1 : pas de fouille sans flagrant délit ; téléphone sur crime + juge fédéral.\nArt. 5 (armes) et 6 (drogues) : objets illicites signalés aux FDO.\nArt. 19.4 : preuve issue d'une fouille illégale = nulle.", "proposition": false}, {"id": "CE.24", "title": "Contrat de travail", "body": "Un contrat de travail existe dès que trois éléments sont réunis : lien de subordination, travail effectif, rémunération.\n\nÀ l'embauche, l'employeur :\n- Fait signer un contrat écrit, rédigé par un avocat (ou par un juge pour les services publics et le DOJ)\n- Vérifie l'identité et l'âge de l'employé (pièce d'identité)\n- Remet par écrit le salaire, le poste et le planning\n- Inscrit l'employé au registre du personnel\n\nLe registre du personnel indique : embauches, démissions ou licenciements, promotions et rétrogradations, type de contrat de chaque salarié.\n\nRupture du CDI : voir l'article « Rupture du contrat de travail à durée indéterminée ».", "penal": "Art. 15.2 : contrat antidaté ou falsifié = faux et usage de faux.", "proposition": false}, {"id": "CE.25", "title": "Employés de direction", "body": "Gérant\nPersonne physique responsable de la direction générale de l'entreprise. Il n'est pas forcément fondateur ou propriétaire mais exerce ses fonctions en vertu des pouvoirs qui lui sont conférés. Il prend les décisions stratégiques, représente légalement l'entreprise et supervise l'ensemble des activités.\n\nManager\nPersonne physique subordonnée au gérant, avec des droits équivalents au prorata. Elle assure la gestion courante en cas d'absence courte du gérant, coordonne les équipes et veille au bon fonctionnement des activités.\n\nTrésorier / Comptable\nPersonne physique chargée de la gestion financière : contrôle des flux financiers, gestion des liquidités, paiement des impôts et taxes. Il peut être chargé des déclarations fiscales.\nRégime : mêmes règles que tout employé (pas de double emploi). S'il est déjà employé à temps plein ailleurs, il ne peut être engagé que comme auto-entrepreneur.\n\nComposition : la direction compte au maximum trois membres, tous statuts confondus.\nConditions d'accès : 21 ans minimum.", "penal": "Règles de procédure, « Culpabilités » : le trésorier qui aide le gérant à frauder est complice (moitié de la peine) ou co-auteur (peine entière).", "proposition": false}, {"id": "CE.26", "title": "Activité commerciale non déclarée", "body": "Définition\nToute entreprise ou opération commerciale exercée sans enregistrement auprès des autorités fiscales ou sans les formalités administratives obligatoires, y compris toute vente de biens ou services en ligne ou en personne.\n\nSanctions\n- Amende pour non-déclaration\n- Pénalités proportionnelles aux revenus générés\n- Fermeture immédiate jusqu'à régularisation complète\n- Redressement fiscal : impôts dus + intérêts de retard + pénalités\n- En cas de récidive ou de fraude avérée : poursuites pénales, la peine dépendant de la gravité et des montants\n\nRégularisation\n- Déclaration spontanée auprès de l'IRS AVANT tout contrôle : peut réduire les pénalités (pas de poursuites pénales si la déclaration est complète et sincère)\n- Paiement échelonné possible sur demande\n- Enregistrement officiel auprès de la mairie et de l'IRS\n- Déclarations périodiques (revenus, taxe de vente le cas échéant)\n- Comptabilité tenue et présentable en cas de contrôle\n- Conformité aux règles commerciales, fiscales, sociales et environnementales", "penal": "Art. 7.5 : fraude fiscale si intentionnelle (2,5 $ x somme non payée + prison fédérale).\nRègles de procédure, « Constitution de l'infraction » : intention ou négligence grave requise.", "proposition": false}, {"id": "CE.27", "title": "Paiement en liquide", "body": "- Une entreprise qui refuse le liquide encaisse par facture (virement, carte, chèque, etc.).\n- Les paiements en liquide supérieurs à 2 000 $ sont interdits, afin de prévenir le blanchiment d'argent et les activités non déclarées.\n- Fractionner volontairement un paiement en plusieurs montants inférieurs au seuil (structuration) est une infraction distincte, même si l'argent est d'origine légale.\n- Tout dépôt ou retrait en liquide de plus de 5 000 $ sur un compte d'entreprise doit pouvoir être justifié auprès de l'IRS.\n\nSanctions (code pénal) :\n- Détention de plus de 2 000 $ en liquide sans justificatif : saisie de l'argent + amende de 50 % de la somme non déclarée (art. 7.1)\n- Blanchiment avéré : amende de 5 $ x la somme blanchie + prison fédérale (art. 7.2)", "penal": "Art. 7.1 : plus de 2 000 $ en liquide sans justificatif = saisie + amende de 50 %.\nArt. 7.2 : blanchiment = 5 $ x somme blanchie + prison fédérale.", "proposition": false}, {"id": "CE.28", "title": "Voiture de fonction", "body": "- Les véhicules de fonction servent principalement à des fins professionnelles.\n- L'usage personnel est interdit sauf autorisation expresse de la direction. Un usage personnel autorisé est un avantage en nature, à déclarer comme revenu de l'employé.\n- Les amendes, contraventions ou délits liés à l'utilisation du véhicule sont à la charge du conducteur responsable.\n- Tout usage non autorisé entraîne des mesures disciplinaires, de l'avertissement à des sanctions plus sévères selon la gravité.", "penal": "Art. 4.6 : le conducteur répond du contenu du véhicule.", "proposition": false}, {"id": "CE.29", "title": "Réglementation sur les EPI", "body": "Les Équipements de Protection Individuelle (EPI) sont tout équipement porté ou utilisé pour limiter l'exposition à des dangers pouvant causer des blessures graves ou des maladies professionnelles : gants, lunettes, chaussures de sécurité, casques, vêtements de protection, masques respiratoires, etc.\n\nObligations de l'employeur\n- Évaluer les risques de chaque poste\n- Fournir gratuitement les EPI adaptés et les maintenir en bon état\n- Former les employés à leur utilisation\n\nObligations des employés\nPorter les EPI adaptés à leur poste. Exemples :\n- Chantier : casque, gants, tenue de chantier\n- Zone à risques chimiques : vêtements adaptés et masque respiratoire\nLe non-respect entraîne des sanctions disciplinaires et engage la responsabilité de l'employé en cas d'accident.", "proposition": false}, {"id": "CE.30", "title": "Tenue de travail", "body": "Les tenues portées en entreprise sont adaptées à la nature du travail (tenue de chantier, uniforme, tenue de bureau, etc.).\nLorsqu'un uniforme spécifique (logo, couleurs) est imposé, il est fourni par l'employeur.\nLe non-respect de ces règles peut entraîner des sanctions disciplinaires prévues au règlement intérieur.", "proposition": false}, {"id": "CE.31", "title": "Facturation des ventes", "body": "Toute entreprise facture ses ventes et services par facture officielle. La facture indique : date, entreprise, client, désignation, montant.\n\nException : les pawnshops (prêts sur gage) sont dispensés de facture, mais tiennent un registre des achats (identité du vendeur, objet, prix, date) consultable par l'IRS et la police.", "penal": "Art. 8.27 : recel (un pawnshop qui achète un bien volé).", "proposition": false}]}, "citoyens": {"key": "citoyens", "label": "Code Citoyen", "updated": "22/11/2026", "intro": "Règles qui s'appliquent à chaque citoyen, en dehors de toute entreprise.", "articles": [{"id": "CC.1", "title": "Vente et achat de véhicules entre particuliers", "body": "Toute vente ou rachat fait l'objet d'un contrat de vente rédigé par un avocat, enregistré au registre des ventes d'occasion tenu par l'IRS. Sans contrat enregistré, le véhicule reste la propriété du précédent propriétaire, même si le transfert a été fait via l'application mobile.\n\nLimite\nDeux transactions par personne sur 30 jours glissants. Un achat suivi de la revente du même véhicule compte pour une seule transaction. Au-delà, la personne est considérée comme exerçant une activité commerciale (voir Code Entreprises, « Régulation de la vente et de l'achat »).\n\nPrix\n- Prix minimum : 60 % du prix concessionnaire du même modèle. Le contrat indique le prix concessionnaire de référence et le prix de vente.\n- Aucune plus-value : un véhicule ne peut pas être revendu plus cher que son prix d'achat.\n- Paiement en liquide limité à 2 000 $, comme pour les entreprises. Au-delà : virement ou facture.\n\nInterdits\n- Le don et l'échange de véhicules\n- Passer par un proche ou un tiers (prête-nom) pour contourner la limite, le prix minimum ou l'interdiction de plus-value\n- La location de véhicules, sauf par une auto-entreprise de location déclarée à l'IRS", "penal": "Art. 7.1 : liquide sans justificatif = saisie + 50 %.\nArt. 8.23 : vol de véhicule (délit mineur, 200 $).\nArt. 8.27 : recel (vendre ou acheter un bien volé).\nArt. 15.3 : usurpation d'identité (prête-nom).\nArt. 15.4 : usage de fausses plaques (délit majeur, 1 000 $ + 40 min).", "proposition": false, "effect": "- Vente sous 60 % : amende égale à la somme manquante pour atteindre 60 % du prix concessionnaire (barème B.19). Le vendeur et l'acheteur en répondent solidairement.\n- Don ou échange : traité comme une vente à 0 $, même sanction (B.19).\n- Plus-value : Saisie de la plus-value (barème B.20).\n- Dépassement de la limite, prête-nom ou location non déclarée : exercice illégal d'une activité professionnelle (barème B.11). Prête-nom : usurpation d'identité (art. 15.3).\n- Paiement en liquide de plus de 2 000 $ : saisie + amende de 50 % (art. 7.1).\n- Sans contrat enregistré : le véhicule reste au précédent propriétaire."}, {"id": "CC.2", "title": "Vente / achat de bien personnel", "body": "La vente ponctuelle d'un bien personnel par un particulier n'est pas une activité commerciale.\nElle le devient en cas de ventes répétées, d'achat de biens dans le but de les revendre, ou de publicité régulière (voir article précédent).\n\nLe vendeur ne doit pas tromper l'acheteur sur l'état ou l'origine du bien. La plus-value réalisée sur la revente d'un bien est un revenu.", "penal": "Art. 8.27 : recel.\nArt. 22.7 : arnaque en ligne.", "proposition": false}, {"id": "CC.3", "title": "Double emploi", "body": "Le double emploi est INTERDIT, sauf dans les bars et boîtes de nuit.\nLa mairie et l'IRS peuvent sanctionner le non-respect de cette règle.", "proposition": false}]}, "fiscalite": {"key": "F", "label": "Fiscalité", "updated": "22/11/2026", "articles": [{"id": "F.1", "title": "Marge d'erreur", "body": "Marge d'erreur acceptée sans justification : aucune.", "effect": "L'IRS peut admettre un droit à l'erreur si celle-ci n'est pas répétée : simple correction de l'impôt, sans sanction financière.", "penal": "Règles de procédure, « Constitution de l'infraction » : sans intention ni négligence grave, pas d'infraction pénale.", "proposition": false}, {"id": "F.2", "title": "Contrôle fiscal", "body": "Ouverture : contrôle de routine, dénonciation ou plainte.\nLe contrôle débute par un avis écrit indiquant son objet et la période contrôlée (il peut être remis sur place, sans préavis).\n\nFormes :\n- Contrôle sur pièces : l'entreprise transmet les documents demandés\n- Contrôle au bureau de l'IRS : le gérant est convoqué\n- Contrôle sur place : dans les locaux de l'entreprise\n\nL'agent a accès à toutes les données contractuelles et comptables, quel que soit le support. Il vérifie :\n- les contrats et l'activité des employés\n- l'état de paiement des impôts\n- la cohérence entre déclarations et justificatifs\n\nAccès aux locaux : avec l'accord du gérant. En cas de refus, l'agent ne force pas l'entrée ; il constate le refus et peut demander un mandat de perquisition (juge + bureau du procureur, valable 14 jours ; art. 2.1 et 2.8).", "effect": "- Avis de contrôle positif si aucune irrégularité : pas de nouveau contrôle avant 2 semaines (sauf élément nouveau).\n- Avis de contrôle négatif : avertissement ou redressement selon les cas.\n\nRefus de contrôle : refuser de communiquer un document que l'on possède = refus de se soumettre au contrôle fiscal : fermeture temporaire ou immédiate de l'entreprise, ou amende de 10 000 $ selon la situation. Si le refus vise à empêcher l'enquête (documents cachés ou détruits), le dossier est transmis au DOJ pour obstruction à la justice (art. 15.8) ou dissimulation de preuves (art. 14.5).", "penal": "Art. 2.1 et 2.8 : mandat pour entrer sans accord.\nArt. 15.8 : obstruction à la justice.\nArt. 14.5 : dissimulation de preuves.", "proposition": false}, {"id": "F.3", "title": "Amende", "body": "Si le contrôle donne lieu à une amende, l'IRS la notifie par écrit à la fin du contrôle, avec le détail de chaque irrégularité et le délai de paiement.", "effect": "- Non payée sous 7 jours : l'amende est doublée (délai prolongeable sur accord de l'IRS).\n- Après majoration, non payée sous 48h : avis final de saisie, puis saisie possible de l'entreprise et des biens (art. 7.6, voir « Recouvrement et saisies »).", "penal": "Art. 7.6 : saisie à la source puis saisie des biens de valeur ; UP si paiement impossible.", "proposition": false}, {"id": "F.4", "title": "Enquête fiscale", "body": "Ouverture : irrégularité de type 2, ou enquête en cours visant un gérant ou un trésorier (soupçon que l'entreprise serve de façade à un trafic).\nAccord préalable d'un juge ou d'un procureur.\n\nPhases :\n1. Enquête administrative par un contrôleur fiscal\n2. Si indices de fraude volontaire : transfert à un agent spécial (enquête criminelle)\n3. Rapport au DOJ, qui décide des poursuites. Procès en cas de crime ou de récidive de délit majeur (Règles de procédure, « Procès » ; art. 21.1)\n\nPérimètre : l'IRS peut remonter 3 mois avant l'ouverture de l'enquête (art. 7.8).\nPerquisitions, fouilles de téléphone et arrestations sont réalisées par les FDO sur mandat (art. 2.1, 2.6, 3.1) ; l'IRS y assiste.\n\nVérifications :\n- solde des comptes à la date d'arrêt\n- retraits des comptes d'entreprise\n- contrats récurrents\n- train de vie des dirigeants comparé aux revenus déclarés", "effect": "- Avis positif si aucune irrégularité\n- Amende pour chaque irrégularité constatée\n- Inculpation selon les faits découverts", "penal": "Art. 2.1 (mandat, 14 jours), 2.6 (mandat d'arrêt), 3.1 (téléphone).\nArt. 7.8 (3 mois).\nArt. 13.1 (association de malfaiteurs), 2.10 (RICO).\nArt. 21.1 et Règles de procédure, « Procès ».", "proposition": false}, {"id": "F.5", "title": "Indices de fraude", "body": "Éléments qui justifient de passer d'un contrôle à une enquête :\n- double comptabilité, fausses écritures ou fausses factures\n- destruction ou dissimulation de documents\n- biens ou comptes cachés, prête-noms\n- usage inhabituel du liquide, structuration\n- revenus ou dépenses sans explication\n- refus de coopérer, déclarations contradictoires", "effect": "Un seul indice ne suffit pas ; c'est leur accumulation qui caractérise la fraude volontaire.", "penal": "Art. 14.5 (dissimulation de preuves), 15.2 (faux), 15.3 (usurpation d'identité, prête-noms).", "proposition": false}, {"id": "F.6", "title": "Méthodes de preuve", "body": "Quand la comptabilité est absente ou fausse, l'IRS reconstitue les revenus :\n- Méthode du patrimoine : hausse du patrimoine + dépenses - revenus déclarés = revenus cachés\n- Méthode des dépôts bancaires : total des dépôts - sommes non imposables\n- Méthode des dépenses : dépenses supérieures aux revenus déclarés", "effect": "Les revenus reconstitués sont imposés et sanctionnés comme une fausse déclaration.", "proposition": false}, {"id": "F.7", "title": "Droit de regard (prescription)", "body": "Fraude fiscale et détournement de fonds : l'IRS peut examiner les 3 mois précédant le début de l'enquête (art. 7.8).\nAppliquer la même durée de 3 mois aux redressements pour simples erreurs de déclaration.", "effect": "Au-delà de 3 mois, plus aucun redressement ni poursuite pour ces faits.", "penal": "Art. 7.8.", "proposition": false}, {"id": "F.8", "title": "Recouvrement et saisies", "body": "Si l'amende ou l'impôt reste impayé (art. 7.3 et 7.6) :\n1. Avis final de saisie remis au gérant\n2. Saisie à la source sur les comptes\n3. Saisie des biens de valeur : véhicules, propriétés, liquidités, bijoux, vêtements de luxe. Les véhicules saisis sont revendus aux enchères, mise à prix 30 % du prix concessionnaire.\n4. Impôts d'entreprise impayés : saisie de l'entreprise + amende (art. 7.3)\n5. Si le paiement est impossible : amende + TIG + bracelet électronique, et conversion du total en UP selon le calculateur de peine (3 $ + total des amendes, puis jugement) (art. 7.6)\n\nAvant l'étape 2, inscription d'une « hypothèque légale » sur les biens de l'entreprise, qui ne peuvent alors plus être vendus.", "effect": "Le dirigeant peut contester la saisie devant un juge.", "penal": "Art. 7.3 et 7.6.", "proposition": false}, {"id": "F.9", "title": "Dénonciation", "body": "Toute personne peut signaler une fraude à l'IRS. L'identité du dénonciateur reste confidentielle.\nUne récompense peut être accordée par le Chef IRS sur les sommes effectivement recouvrées.\nUn employé qui signale une fraude ne peut pas être licencié pour ce motif.", "effect": "Une dénonciation mensongère est sanctionnable : diffamation (art. 12.8), parjure si elle est faite sous serment (art. 15.1). Faire pression sur un dénonciateur ou un témoin : art. 15.6.", "penal": "Art. 12.8 (diffamation), 15.1 (parjure), 15.6 (influence de témoin).", "proposition": false}], "bareme": [{"id": "B.1", "infraction": "Impôts : retard de déclaration de moins d'une semaine", "type1": "1 000 $ + somme due + 10 % d'intérêts", "type2": "2 000 $ + somme due + 30 % d'intérêts", "penal": "", "proposition": false}, {"id": "B.2", "infraction": "Impôts : oubli de déclaration (retard de plus d'une semaine)", "type1": "2 000 $ + somme due + 30 % d'intérêts", "type2": "3 000 $ + somme due + 50 % d'intérêts", "penal": "", "proposition": false}, {"id": "B.3", "infraction": "Non-paiement des impôts", "type1": "3 000 $ x nombre de semaines", "type2": "3 000 $ x nombre de semaines", "penal": "Art. 7.3 : saisie de l'entreprise + amende.", "proposition": false}, {"id": "B.4", "infraction": "Impôts : fausse déclaration", "type1": "5 000 $ + somme manquante + 25 % d'intérêts", "type2": "10 000 $ + somme manquante + 25 % d'intérêts ; si volontaire, transmission au DOJ pour fraude fiscale (art. 7.5)", "penal": "Art. 7.5 si volontaire.", "proposition": false}, {"id": "B.5", "infraction": "Contrat de travail / visite médicale inexistant ou obsolète", "type1": "500 $ par contrat", "type2": "1 000 $ par contrat", "penal": "Art. 15.2 si document falsifié.", "proposition": false}, {"id": "B.6", "infraction": "Contrat d'actionnaire inexistant ou obsolète", "type1": "500 $ par contrat", "type2": "1 000 $ par contrat", "penal": "", "proposition": false}, {"id": "B.7", "infraction": "Contrat de partenariat inexistant ou obsolète", "type1": "1 000 $ par contrat", "type2": "2 000 $ par contrat", "penal": "", "proposition": false}, {"id": "B.8", "infraction": "Règlement intérieur inexistant ou incomplet", "type1": "1 000 $ si inexistant ; avertissement si incomplet", "type2": "2 000 $ si inexistant ; 1 000 $ si incomplet", "penal": "", "proposition": false}, {"id": "B.9", "infraction": "Non-respect des salaires imposés par le gouvernement", "type1": "3 000 $ + amende égale au trop-perçu + 10 % d'intérêts, par employé", "type2": "3 000 $ + amende égale au trop-perçu + 30 % d'intérêts, par employé", "penal": "", "proposition": false}, {"id": "B.10", "infraction": "Vente de produits non autorisés", "type1": "150 $ par produit + saisie", "type2": "400 $ par produit + saisie", "penal": "Art. 5 (armes) et 6 (drogues) si produits illicites.", "proposition": false}, {"id": "B.11", "infraction": "Exercice illégal d'une activité professionnelle", "type1": "10 000 $", "type2": "20 000 $", "penal": "", "proposition": false}, {"id": "B.12", "infraction": "Acquisition de véhicule d'entreprise sans accord de l'IRS", "type1": "70 % du prix d'achat + saisie du ou des véhicules", "type2": "70 % du prix d'achat + saisie du ou des véhicules + révocation du gérant", "penal": "Art. 7.6 (saisie).", "proposition": false}, {"id": "B.13", "infraction": "Publicité ou annonce mensongère ou trompeuse (réseaux, application Annonces) envers clients, candidats ou autres", "type1": "5 000 $", "type2": "10 000 $", "penal": "Art. 22.7.", "proposition": false}, {"id": "B.14", "infraction": "Structuration : fractionnement de paiements en liquide pour rester sous le seuil", "type1": "5 000 $ + saisie des sommes concernées", "type2": "10 000 $ + transmission au DOJ", "penal": "Art. 7.1 et 7.2.", "proposition": false}, {"id": "B.15", "infraction": "Production de documents faux ou falsifiés lors d'un contrôle", "type1": "10 000 $ + transmission au DOJ (faux et usage de faux, art. 15.2)", "type2": "20 000 $ + transmission au DOJ (art. 15.2)", "penal": "Art. 15.2.", "proposition": false}, {"id": "B.16", "infraction": "Registre du personnel ou justificatifs comptables absents", "type1": "1 000 $", "type2": "2 000 $", "penal": "Art. 14.5 si détruits volontairement.", "proposition": false}, {"id": "B.17", "infraction": "Faux auto-entrepreneur (salarié déguisé en indépendant)", "type1": "2 000 $ par personne + régularisation", "type2": "4 000 $ par personne + régularisation", "penal": "", "proposition": false}, {"id": "B.18", "infraction": "Solde de tout compte payé en retard", "type1": "Pénalité de l'article « Solde de tout compte »", "type2": "Double pénalité", "penal": "", "proposition": false}, {"id": "B.19", "infraction": "Véhicule vendu sous 60 % du prix concessionnaire (y compris don ou échange)", "type1": "Somme manquante pour atteindre 60 % du prix concessionnaire", "type2": "Somme manquante pour atteindre 60 % du prix concessionnaire", "penal": "Art. 7.4 si véhicule d'entreprise et prix détourné.", "proposition": false}, {"id": "B.20", "infraction": "Plus-value sur la revente d'un véhicule entre particuliers", "type1": "Saisie de la plus-value", "type2": "Saisie de la plus-value + 1 000 $", "penal": "", "proposition": false}], "fraude": "La fraude fiscale est le contournement illégal de l'impôt : dissimuler des revenus, gonfler des charges, mentir sur une déclaration. L'optimisation fiscale consiste à réduire légalement son impôt en utilisant les règles existantes.\nUn montage qui n'a aucune utilité économique réelle en dehors de l'économie d'impôt est requalifié et sanctionné.\n\nCode pénal : fraude fiscale, amende de 2,5 $ x la somme non payée + prison fédérale (art. 7.5) ; détournement de fonds, 2 $ x la somme détournée + prison fédérale (art. 7.4) ; blanchiment, 5 $ x la somme blanchie + prison fédérale (art. 7.2). Il n'y a infraction pénale que s'il y a intention ou négligence grave (Règles de procédure, « Constitution de l'infraction ») ; une erreur de bonne foi relève seulement du redressement administratif de l'IRS. Le complice est puni de la moitié de la peine, le co-auteur de la peine entière (Règles de procédure, « Culpabilités »)."}, "impots": {"key": "I", "label": "Impôts", "updated": "31/10/2026", "articles": [{"id": "I.1", "title": "Modalités de fonctionnement", "body": "Entités concernées\nDoivent déclarer et payer leurs impôts :\n- Entreprises commerciales\n- Organisations à but lucratif (hors événementiel)\n- Salons de coiffure\n- Salons de tatouage\n- Cabinets d'avocats\n- Auto-entrepreneurs\n- Toute autre activité professionnelle non exonérée\n\nPériode\nLes impôts sont calculés chaque semaine, du lundi 00h00 au dimanche 23h59.\n\nCe qu'il faut déclarer\n- Les paiements par facture bancaire ou carte sont taxés automatiquement.\n- Tout autre encaissement (liquide, virement hors facture, etc.) doit être déclaré.\n- La base est le chiffre d'affaires de la semaine (voir « Taux d'imposition »).\n\nDélai\nEn semaine 34, on déclare et paie les impôts de la semaine 33, au plus tard le mardi 23h59.\n\nSemaine sans bénéfice\nUn résultat nul ou négatif est quand même déclaré, avec une déclaration symbolique de 1 $.", "penal": "Art. 7.3 : impôts non payés = saisie de l'entreprise + amende.", "proposition": false}, {"id": "I.2", "title": "Retard de paiement", "body": "- Les retards ne sont pas acceptés, sauf dérogation exceptionnelle accordée sur demande justifiée auprès de l'IRS, AVANT la date limite.\n- Toute déclaration hors délai est majorée selon le barème de l'onglet « Fiscalité ».\n- En cas d'oubli de déclaration, même pour un résultat nul ou négatif, l'amende prévue au barème des sanctions (« Oubli de déclaration ») est appliquée.", "penal": "Art. 7.3.", "proposition": false}, {"id": "I.3", "title": "Déclaration des impôts", "body": "Pour les entreprises ou organisations ne fonctionnant pas uniquement par factures (taxées automatiquement) :\n\n1. Déclarer les revenus de la semaine sur la fiche impôts.\n2. Se rendre à la banque ou à un ATM.\n3. Faire un virement du montant indiqué sur la fiche vers le compte du gouvernement : IBAN GOUV ou IBAN IRS.\n4. Conserver la preuve de virement et la joindre à la fiche impôts.\n5. Procédure terminée.\n\nImportant : un résultat nul ou négatif impose quand même une déclaration symbolique de 1 $.", "proposition": false}, {"id": "I.4", "title": "Conservation des justificatifs", "body": "Chaque entreprise conserve ses factures, preuves de virement, contrats, registre du personnel et fiches impôts pendant au moins 3 mois, soit la durée sur laquelle l'IRS peut remonter (art. 7.8). L'absence de justificatif lors d'un contrôle est traitée comme une déclaration non justifiée. Détruire volontairement des documents pendant un contrôle ou une enquête constitue une dissimulation de preuves (art. 14.5).", "penal": "Art. 7.8 : droit de regard de 3 mois.\nArt. 14.5 : détruire des documents = dissimulation de preuves.", "proposition": false}, {"id": "I.5", "title": "Salaires", "body": "Pour les grilles salariales obligatoires (secteur privé, public et auto-entrepreneur), consulter le Référent Entreprise ou l'IRS.\nDocument de référence : grille des salaires (entreprise privée, publique et auto-entrepreneur), disponible auprès du Référent Entreprise ou de l'IRS.\n\nLe salaire est versé selon la grille, et chaque versement est tracé (facture, virement ou fiche de paie).", "proposition": false}, {"id": "I.6", "title": "Subventions", "body": "- Les subventions reçues par une entreprise sont des produits non imposables : elles n'entrent pas dans le calcul de l'impôt.\n- Les salaires financés par une subvention ne peuvent pas être déduits ou déclarés une seconde fois.\n- L'entreprise conserve la convention de subvention et justifie l'usage des fonds sur demande de l'IRS.", "proposition": false}, {"id": "I.7", "title": "Taux d'imposition", "body": "L'imposition est calculée sur le chiffre d'affaires de la semaine (lundi 00h00 au dimanche 23h59), avant déduction des charges.\nLe taux applicable est fixé par le gouvernement (voir le Référent Entreprise ou l'IRS).", "proposition": false}, {"id": "I.8", "title": "Bénéfice restant", "body": "Le bénéfice restant est la somme qui reste après déduction des salaires, des charges et des impôts. Il alimente la trésorerie de l'entreprise.", "proposition": false}, {"id": "I.9", "title": "Trésorerie", "body": "La trésorerie est l'ensemble des liquidités détenues par l'entreprise. Elle sert à payer les charges, les salaires et les besoins financiers de l'entreprise.\nCet argent appartient à l'entreprise. Son utilisation pour des dépenses personnelles d'un dirigeant, sans contrat ni décision écrite, constitue un détournement de fonds.", "penal": "Art. 7.4 : détournement de fonds, 2 $ x somme détournée + prison fédérale.", "proposition": false}, {"id": "I.10", "title": "Difficultés de paiement", "body": "Une entreprise en difficulté peut demander à l'IRS, AVANT l'échéance :\n- Un paiement échelonné (2 à 4 semaines), avec intérêts\n- Une remise des pénalités (pas des impôts) si le retard a une cause sérieuse et justifiée, ou s'il s'agit d'un premier manquement sans antécédent depuis 4 semaines\nLa demande est validée par le Chef IRS.", "penal": "Art. 7.6 : si le paiement est impossible, conversion en UP (calculateur de peine).", "proposition": false}]}, "organisation": {"key": "IRS", "label": "Organisation IRS", "updated": "31/10/2026", "intro": "L'Internal Revenue Service (IRS) vérifie le respect des lois économiques et fiscales de l'État de San Andreas. Il contrôle et enquête sur les entreprises et organisations, privées ou publiques.\n\nL'IRS est un service placé sous la supervision du DOJ. Les poursuites pénales qu'il prépare sont engagées par le DOJ.", "articles": [{"id": "IRS.1", "title": "Chef IRS", "body": "Directeur de l'IRS.\n- Veille au bon fonctionnement de l'IRS\n- Recrute les agents, les sanctionne ou les renvoie en cas de faute\n- Valide les saisies d'entreprise\n- Supervise contrôles et enquêtes fiscales\n- Répartit les dossiers entre les agents\n- Valide les amendes\n- Statue sur les contestations et les demandes d'échelonnement", "proposition": false}, {"id": "IRS.2", "title": "Agent IRS (contrôleur fiscal)", "body": "Inspecteur de l'IRS.\n- Contrôle la fiscalité des entreprises privées et publiques\n- Conseille les citoyens sur leur situation fiscale personnelle ou professionnelle\n- Lance un contrôle sous la direction du Chef IRS, ou à la demande du Gouvernement ou du DOJ\n- Enquête dans une entreprise sur demande du Chef IRS\n\nPouvoirs :\n- Contrôle sans préavis d'une entreprise ou d'un service public\n- Accès total aux documents comptables et contractuels pendant un contrôle\n- Accès aux comptes professionnels sans autorisation préalable\n- Accès aux comptes des particuliers uniquement sur mandat d'un procureur ou d'un juge, avec motif valable\n- Demande de justificatifs pour tout mouvement de plus de 5 000 $\n- Présence aux perquisitions issues d'un contrôle fiscal\n- Amendes pour les irrégularités constatées\n- Transmission du rapport au DOJ si irrégularités graves\n\nEn enquête fiscale, sur accord préalable d'un procureur ou d'un juge : accès aux comptes personnels du gérant et du trésorier en cas de soupçon de blanchiment, détournement ou fraude.\nSur accord du DOJ, gel des biens du gérant ou trésorier jusqu'à décision : saisie des véhicules, gel des comptes bancaires.", "proposition": false}, {"id": "IRS.3", "title": "Agent de recouvrement", "body": "Chargé du recouvrement des impôts et amendes impayés : avis finaux, échéanciers, hypothèques légales et saisies validées par le Chef IRS.", "proposition": false}, {"id": "IRS.4", "title": "Agent spécial - enquêtes criminelles", "body": "Unité d'enquête criminelle de l'IRS : blanchiment, fraude fiscale volontaire, structuration, financement d'activités criminelles.\nPeut, dans le cadre de ses enquêtes, participer aux perquisitions et saisies sur mandat. Les arrestations restent faites par les FDO (SASP, BCSO, LSPD, US Marshall), seules citées par le code pénal.", "proposition": false}, {"id": "IRS.5", "title": "Devoirs de tous les agents", "body": "- Confidentialité absolue des informations fiscales\n- Interdiction de consulter un dossier sans mission\n- Interdiction de contrôler une entreprise où l'agent a un intérêt personnel\n- Remise d'un avis écrit au début de tout contrôle\n- Conflit d'intérêts : le déclarer à sa hiérarchie et ne pas participer au dossier (Règles de procédure, « Le conflit d'intérêt »)\n- Abus de pouvoir sanctionné (art. 12.10) ; divulgation d'informations confidentielles sanctionnée (art. 16.6)\n- Pas de fouille de personnes, de véhicules ni de téléphones (art. 1.2, 3.1 à 3.3 : réservées aux FDO et au juge fédéral)", "proposition": false}, {"id": "IRS.6", "title": "Définitions", "body": "* Un poste bénéficie des compétences des postes qui le précèdent dans la hiérarchie.", "proposition": false}]}};
